import streamlit as st
import pandas as pd

@st.cache_data
def carregar_turma():
    return pd.DataFrame({
        "Aluno": ["Ana", "Carlos", "Beatriz", "Diego", "Elisa"],
        "Módulo": ["Python", "JavaScript", "Python", "Streamlit", "JavaScript"],
        "Nota": [8.5, 6.0, 9.5, 7.0, 5.5],
    })

if "favoritos" not in st.session_state:
    st.session_state.favoritos = []

df = carregar_turma()

with st.sidebar:
    st.header("Filtros")
    modulos = st.multiselect("Módulos", df["Módulo"].unique(), default=list(df["Módulo"].unique()))
    nota_min = st.slider("Nota mínima", 0.0, 10.0, 0.0, step=0.5)

st.title("Painel de Notas da Turma")
filtrado = df[(df["Módulo"].isin(modulos)) & (df["Nota"] >= nota_min)]

if filtrado.empty:
    st.warning("Nenhum aluno com esses filtros.")
else:
    st.dataframe(filtrado)
    media = filtrado["Nota"].mean()
    if media >= 7:
        st.success(f"Média do grupo: {media:.2f}")
    else:
        st.error(f"Média do grupo: {media:.2f}")

st.divider()
aluno = st.selectbox("Marcar aluno como destaque", df["Aluno"])
if st.button("Adicionar destaque"):
    if aluno not in st.session_state.favoritos:
        st.session_state.favoritos.append(aluno)

st.write("Destaques:", st.session_state.favoritos)

