import streamlit as st

peso = st.number_input("Peso (kg)", min_value=0.0)
altura = st.number_input("Altura (m)", min_value=0.0)
if st.button("Calcular"):
    if altura > 0:
        imc = peso / altura ** 2
        st.write(f"IMC: {imc:.2f}")
        if imc > 25:
            st.warning("Acima de 25.")
    else:
        st.error("Informe a altura.")

