import streamlit as st
import pandas as pd

@st.cache_data
def carregar_notas():
    return pd.DataFrame({"Aluno": ["Ana", "Carlos", "Beatriz"], "Nota": [8.5, 6.0, 9.5]})

df = carregar_notas()
escolhidos = st.multiselect("Alunos", df["Aluno"], default=list(df["Aluno"]))
sel = df[df["Aluno"].isin(escolhidos)]
st.dataframe(sel)
if not sel.empty:
    st.write(f"Média: {sel['Nota'].mean():.2f}")

